{
  "title": "functions.expression.AnyOfInputSchema",
  "description": "Schema for a union of possible types - input must match at least one.",
  "type": "object",
  "properties": {
    "anyOf": {
      "description": "The possible schemas that the input can match.",
      "type": "array",
      "items": {
        "$ref": "functions.expression.InputSchema"
      }
    }
  }
}

{
  "title": "functions.expression.ObjectInputSchema",
  "description": "Schema for an object input with named properties.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the object.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ]
    },
    "properties": {
      "additionalProperties": {
        "$ref": "functions.expression.InputSchema"
      },
      "description": "Schema for each property in the object.",
      "type": "object"
    },
    "required": {
      "description": "List of property names that must be present.",
      "anyOf": [
        {
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        {
          "type": "null"
        }
      ]
    },
    "type": {
      "$ref": "functions.expression.ObjectInputSchemaType"
    }
  }
}

{
  "title": "functions.expression.ObjectInputSchemaType",
  "type": "string",
  "enum": [
    "object"
  ]
}

{
  "title": "agent.completions.message.RichContentPart",
  "description": "A part of rich content.",
  "anyOf": [
    {
      "description": "Text content.",
      "type": "object",
      "properties": {
        "text": {
          "type": "string"
        },
        "type": {
          "type": "string",
          "enum": [
            "text"
          ]
        }
      }
    },
    {
      "description": "An image URL.",
      "type": "object",
      "properties": {
        "image_url": {
          "$ref": "agent.completions.message.ImageUrl"
        },
        "type": {
          "type": "string",
          "enum": [
            "image_url"
          ]
        }
      }
    },
    {
      "description": "Audio input.",
      "type": "object",
      "properties": {
        "input_audio": {
          "$ref": "agent.completions.message.InputAudio"
        },
        "type": {
          "type": "string",
          "enum": [
            "input_audio"
          ]
        }
      }
    },
    {
      "description": "Video input.",
      "type": "object",
      "properties": {
        "type": {
          "type": "string",
          "enum": [
            "input_video"
          ]
        },
        "video_url": {
          "$ref": "agent.completions.message.VideoUrl"
        }
      }
    },
    {
      "description": "A video URL.",
      "type": "object",
      "properties": {
        "type": {
          "type": "string",
          "enum": [
            "video_url"
          ]
        },
        "video_url": {
          "$ref": "agent.completions.message.VideoUrl"
        }
      }
    },
    {
      "description": "A file.",
      "type": "object",
      "properties": {
        "file": {
          "$ref": "agent.completions.message.File"
        },
        "type": {
          "type": "string",
          "enum": [
            "file"
          ]
        }
      }
    }
  ]
}

{
  "title": "agent.completions.message.RichContent",
  "description": "Rich content for user/assistant messages (supports multimodal input).",
  "anyOf": [
    {
      "description": "Plain text content.",
      "type": "string"
    },
    {
      "description": "Multi-part content (text, images, audio, video, files).",
      "type": "array",
      "items": {
        "$ref": "agent.completions.message.RichContentPart"
      }
    }
  ]
}

{
  "title": "agent.completions.message.SimpleContentPartExpression",
  "description": "A text part expression.",
  "type": "object",
  "properties": {
    "text": {
      "description": "A value that can be either a literal or an expression.\n\nThis allows Function definitions to mix static values with dynamic\nexpressions. During compilation, expressions are evaluated while\nliteral values pass through unchanged.\n\n# Example\n\nLiteral value:\n```json\n\"hello world\"\n```\n\nJMESPath expression:\n```json\n{\"$jmespath\": \"input.greeting\"}\n```\n\nStarlark expression:\n```json\n{\"$starlark\": \"input['greeting']\"}\n```",
      "anyOf": [
        {
          "description": "An expression (JMESPath or Starlark) to evaluate.",
          "$ref": "functions.expression.Expression"
        },
        {
          "description": "A literal value.",
          "type": "string"
        }
      ]
    },
    "type": {
      "type": "string",
      "enum": [
        "text"
      ]
    }
  }
}

